#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int N = 50005;
const int K = 6; // k 的最大值 + 1
const int NEG_INF = -1e9;

int n, m;
int A[N];
vector<int> adj[N];

// 树链剖分数组
int fa[N], dep[N], siz[N], son[N];
int top_node[N], dfn[N], rnk[N], tot;

void dfs1(int u, int p, int d) {
    fa[u] = p; dep[u] = d; siz[u] = 1; son[u] = 0;
    int max_siz = 0;
    for (int v : adj[u]) {
        if (v == p) continue;
        dfs1(v, u, d + 1);
        siz[u] += siz[v];
        if (siz[v] > max_siz) { max_siz = siz[v]; son[u] = v; }
    }
}

void dfs2(int u, int t) {
    top_node[u] = t; dfn[u] = ++tot; rnk[tot] = u;
    if (son[u]) dfs2(son[u], t);
    for (int v : adj[u]) {
        if (v == fa[u] || v == son[u]) continue;
        dfs2(v, v);
    }
}

// 线段树节点，维护链上的 DP 状态
// dp[0][j]: 右端点不选，选了 j 个块的 max 权值
// dp[1][j]: 右端点选了，选了 j 个块的 max 权值
struct Node {
    int dp[2][K];
    bool open; // 标记该区间是否为路径端点
    
    void init(int val, bool is_open) {
        open = is_open;
        for (int j = 0; j < K; ++j) dp[0][j] = dp[1][j] = NEG_INF;
        dp[0][0] = 0;
        if (is_open) {
            // 端点只能作为第 1 个块的开头
            dp[1][1] = val; 
        } else {
            // 非端点，既可以接续前块，也可以作为新块开头
            dp[1][1] = val;
            dp[1][0] = 0; // (这行其实被dp[0][0]覆盖，合并时体现)
        }
    }
    
    void reverse() {
        // 链反转，DP含义左右对称，数组无需改动，仅翻转 open 标记
        open = !open; 
    }
};

Node tree[N << 2];

// 优化：O(k) 闵可夫斯基和加速卷积合并
void max_conv(int res[], const int a[], const int b[], int k) {
    for (int j = 0; j <= k; ++j) res[j] = NEG_INF;
    int pb = 0;
    for (int pa = 0; pa <= k; ++pa) {
        if (a[pa] == NEG_INF) continue;
        while (pb < k && b[pb + 1] >= b[pb]) ++pb; // 寻找 b 的峰值
        if (b[pb] != NEG_INF) res[pa + pb] = max(res[pa + pb], a[pa] + b[pb]);
    }
    // 补漏：由于峰可能偏移，补全所有可能组合
    pb = 0;
    for (int pa = 0; pa <= k; ++pa) {
        if (a[pa] == NEG_INF) continue;
        while (pb < k && (b[pb + 1] >= b[pb] || pa + pb + 1 > k)) ++pb;
        if (pb > 0 && b[pb - 1] != NEG_INF) res[pa + pb - 1] = max(res[pa + pb - 1], a[pa] + b[pb - 1]);
        if (b[pb] != NEG_INF) res[pa + pb] = max(res[pa + pb], a[pa] + b[pb]);
    }
}

Node merge(const Node& L, const Node& R) {
    Node res;
    res.open = false;
    for (int j = 0; j < K; ++j) res.dp[0][j] = res.dp[1][j] = NEG_INF;
    
    // res.dp[0][j]: L 和 R 拼接后，R 端点不选
    for (int j = 0; j < K; ++j) {
        res.dp[0][j] = max(L.dp[0][j], L.dp[1][j]);
        if (res.dp[0][j] < R.dp[0][j] && R.dp[0][j] != NEG_INF) 
            res.dp[0][j] = R.dp[0][j]; // R 独立成块
    }
    
    // res.dp[1][j]: R 端点选了
    // 情况 1: R 是接续 L 的块
    max_conv(res.dp[1], L.dp[1], R.dp[1], K - 1);
    
    // 情况 2: R 独立作为一个新块开头
    for (int j = 1; j < K; ++j) {
        int best_L = max(L.dp[0][j - 1], L.dp[1][j - 1]);
        if (best_L != NEG_INF && R.dp[1][1] != NEG_INF) {
            res.dp[1][j] = max(res.dp[1][j], best_L + R.dp[1][1]);
        }
    }
    return res;
}

void build(int rt, int l, int r) {
    if (l == r) { tree[rt].init(A[rnk[l]], true); return; }
    int mid = (l + r) >> 1;
    build(rt << 1, l, mid); build(rt << 1 | 1, mid + 1, r);
    tree[rt] = merge(tree[rt << 1], tree[rt << 1 | 1]);
}

void update(int rt, int l, int r, int pos, int val) {
    if (l == r) { tree[rt].init(val, true); return; }
    int mid = (l + r) >> 1;
    if (pos <= mid) update(rt << 1, l, mid, pos, val);
    else update(rt << 1 | 1, mid + 1, r, pos, val);
    tree[rt] = merge(tree[rt << 1], tree[rt << 1 | 1]);
}

Node query(int rt, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) return tree[rt];
    int mid = (l + r) >> 1;
    if (qr <= mid) return query(rt << 1, l, mid, ql, qr);
    if (ql > mid) return query(rt << 1 | 1, mid + 1, r, ql, qr);
    return merge(query(rt << 1, l, mid, ql, qr), query(rt << 1 | 1, mid + 1, r, ql, qr));
}

int query_path(int u, int v, int k) {
    Node resL, resR;
    bool hasL = false, hasR = false;
    
    while (top_node[u] != top_node[v]) {
        if (dep[top_node[u]] > dep[top_node[v]]) {
            Node cur = query(1, 1, n, dfn[top_node[u]], dfn[u]);
            if (hasL) resL = merge(cur, resL); else resL = cur;
            hasL = true;
            u = fa[top_node[u]];
        } else {
            Node cur = query(1, 1, n, dfn[top_node[v]], dfn[v]);
            cur.reverse();
            if (hasR) resR = merge(resR, cur); else resR = cur;
            hasR = true;
            v = fa[top_node[v]];
        }
    }
    
    Node mid_res;
    if (dep[u] < dep[v]) mid_res = query(1, 1, n, dfn[u], dfn[v]);
    else { mid_res = query(1, 1, n, dfn[v], dfn[u]); mid_res.reverse(); }
    
    Node final_res = hasL ? merge(resL, mid_res) : mid_res;
    if (hasR) final_res = merge(final_res, resR);
    
    return max(final_res.dp[0][k], final_res.dp[1][k]);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    
    if (!(cin >> n >> m)) return 0;
    for (int i = 1; i <= n; ++i) cin >> A[i];
    for (int i = 1; i < n; ++i) {
        int u, v; cin >> u >> v;
        adj[u].push_back(v); adj[v].push_back(u);
    }
    
    dfs1(1, 0, 1); dfs2(1, 1); build(1, 1, n);
    
    while (m--) {
        int op; cin >> op;
        if (op == 1) {
            int u, x; cin >> u >> x;
            update(1, 1, n, dfn[u], x);
        } else if (op == 2) {
            int u, v, k; cin >> u >> v >> k;
            cout << query_path(u, v, k) << "\n";
        }
    }
    return 0;
}
